// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        address admin = address(this);

        // Rule: only the admin can change owner.
        if (actor == admin) {
            vm.prank(actor);
            bool ok;
            try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
            assertTrue(ok && c.owner() == newOwner);
        } else {
            vm.prank(actor);
            bool ok;
            try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
            assertTrue(!ok && c.owner() == admin,
                "non-admin must not be able to set owner");
        }
    }
}
